clear;
clc;
close all;

% Time values from 0 to 20 seconds
t = 0:0.2:20;

% Speed equation
v = -0.2 .* (t - 10).^2 + 20;

% Plot speed vs time
figure; %[output:53f937d1]
plot(t, v, 'LineWidth', 2); %[output:53f937d1]
grid on; %[output:53f937d1]
xlabel('Time (seconds)'); %[output:53f937d1]
ylabel('Speed'); %[output:53f937d1]
title('Speed vs Time'); %[output:53f937d1]

% Estimate acceleration using numerical differences
acceleration = diff(v) ./ diff(t);

% Time values for acceleration plot
t_acceleration = t(1:end-1);

% Plot acceleration vs time
figure; %[output:3214ce79]
plot(t_acceleration, acceleration, 'LineWidth', 2); %[output:3214ce79]
grid on; %[output:3214ce79]
xlabel('Time (seconds)'); %[output:3214ce79]
ylabel('Acceleration'); %[output:3214ce79]
title('Acceleration vs Time'); %[output:3214ce79]

% Find maximum speed
[maxSpeed, index] = max(v);
timeMaxSpeed = t(index);

% Find acceleration near the maximum speed
[~, accelIndex] = min(abs(t_acceleration - timeMaxSpeed));
accelNearMax = acceleration(accelIndex);

% Display results
disp("Maximum speed:"); %[output:35c0b9f9]
disp(maxSpeed); %[output:059698b8]

disp("Time when speed is maximized:"); %[output:2e75a698]
disp(timeMaxSpeed); %[output:9e4565a3]

disp("Acceleration near maximum speed:"); %[output:5f55d559]
disp(accelNearMax); %[output:9c22658c]

